$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT DisplayName, Coordinates, Bundesland FROM WicLocations WHERE DisplayName LIKE '%Essen%'"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0] '|' $r[1] '|' $r[2]}; $conn.Close(); Write-Host "---done---"
